{"chunk_key": "c1", "registry_id": "BSR-MA-02", "locator": "Article I. Of God and the Creation of all Things", "phrase": "one eternal, almighty, and incomprehensible God, the Father, Son, and Holy Ghost", "rationale": "Confesses the one God as Father together with Son and Holy Ghost, asserting divine paternity as an identity of God.", "floor_claim": "FULL"},
{"chunk_key": "c5", "registry_id": "BSR-MA-02", "locator": "Article V. The Law of Christ, i.e., the Holy Gospel or the New Testament", "phrase": "as containing the whole counsel and will of His heavenly Father", "rationale": "Names God as Father in relation to the Son, asserting the relational identity of Father, though narrower in scope.", "floor_claim": "PARTIAL"},
{"chunk_key": "c7", "registry_id": "BSR-MA-02", "locator": "Article VII. Of Holy Baptism", "phrase": "in the most worthy name of the Father, and of the Son, and of the Holy Ghost", "rationale": "Mentions the divine name Father within the baptismal formula but does not itself assert a proposition about God's paternity.", "floor_claim": "WORD_ONLY"}
